import { useState, useEffect } from 'react';
import { getTasks } from '../../api';
import type { Task } from '../../types';
import './TaskBoard.css';

const SKELETON_COUNT = 3;

export function TaskBoard(): JSX.Element {
  const [tasks, setTasks] = useState<Task[] | null>(null);

  useEffect(() => {
    getTasks()
      .then((data) => setTasks(data))
      .catch(() => setTasks([]));
  }, []);

  const isLoading = tasks === null;
  const isEmpty = tasks !== null && tasks.length === 0;

  return (
    <div className="task-board">
      <header className="task-board-header">
        <h1 className="task-board-title">Tasks</h1>
        {!isLoading && (
          <span className="task-board-count-badge">{tasks.length}</span>
        )}
      </header>
      <div className="task-board-filter-bar" />
      <ul className="task-board-list">
        {isLoading &&
          Array.from({ length: SKELETON_COUNT }, (_, i) => (
            <li key={i} className="task-board-skeleton" />
          ))}
        {isEmpty && (
          <li className="task-board-empty">No tasks found.</li>
        )}
        {!isLoading && !isEmpty && tasks.map((task) => (
          <li key={task.id} className="task-board-item">
            {task.title}
          </li>
        ))}
      </ul>
    </div>
  );
}
